int far gr_BitMapSize(int far * size, int object)
{
    unsigned int handle;
    struct BitmapBlock far *block;
    struct BitmapHeader header;
    int far * p;

    handle = db_LoadObject(object, 2, 1);
    if (handle == 0) {
        size[0] = size[1] = 1;
        return 0;
    }
    block = (struct BitmapBlock far *)mem_Lock(handle);
    if (block->packed == -1) {
        UnpackInit(block->data, block->length);
        Unpack((void far *)&header, 12);
        p = size;
        p[0] = header.size.x;
        p[1] = header.size.y;
    } else {
        size[0] = block->width;
        size[1] = block->height;
    }
    mem_Unlock(handle);
    db_ReleaseObject(object, 2);
    return 1;
}
